# compute convex hull and lattice inclusion for D2; report discrepancies vs fill
pts=D2
pts2=sorted(set((c,r) for r,c in pts))
def hull(points):
    points=sorted(points)
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in points:
        while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    up=[]
    for p in reversed(points):
        while len(up)>=2 and cross(up[-2],up[-1],p)<=0: up.pop()
        up.append(p)
    return lo[:-1]+up[:-1]
H=hull(pts2);H

# fill gaps along r-c constant lines with >=2 marker points
from collections import defaultdict
d=defaultdict(list)
for r,c in D2:d[r-c].append((r,c))
gapplus=set()
for t,pp in d.items():
    if len(pp)>=2:
        a=min(r for r,c in pp); b=max(r for r,c in pp)
        for r in range(a+1,b): gapplus.add((r,r-t))
print('gap plus',len(gapplus),'out',len(out2),'match',len(gapplus&set(out2)),'missed out',len(set(out2)-gapplus),'extra',len(gapplus-set(out2)))
print('missed examples',sorted(set(out2)-gapplus)[:100])
print('extra examples',sorted(gapplus-set(out2))[:100])

